{"command":"# Let me analyze the dumps to extract path conditions and symbolic vars
python3 << 'PY'
import json

dumps = []
for i in range(1, 4):
    d = json.load(open(f'/work/out/packet/dumps/dump_anon_json_dse{i:04d}.json'))
    dumps.append(d)

# Collect all symbolic vars info
all_vars = {}
for d in dumps:
    for sv in d.get('symbolic_vars', []):
        name = sv.get('name', '?')
        sort = sv.get('sort', '?')
        value = sv.get('value', '?')
        note = sv.get('note', '')
        if name not in all_vars:
            all_vars[name] = {'sort': sort, 'first_value': value, 'note': note[:80]}
        else:
            if all_vars[name]['first_value'] != value:
                all_vars[name]['diff'] = True

# Print all vars
for name, info in sorted(all_vars.items()):
    diff = " [Varies]" if info.get('diff') else ""
    print(f"  {name}: {info['sort']} = {info['first_value']}{diff}")
    if info['note']:
        print(f"    note: {info['note']}")

print(f"\nTotal symbolic vars: {len(all_vars)}")
PY","description":"Extract assumptions from dumps"}

